export class TravelError extends Error {
    code;
    constructor(code, message) { super(`${code}: ${message}`); this.name = 'TravelError'; this.code = code; }
}
export function cents(raw) { const v = raw.trim().replace(/[¥￥,\s]/g, ''); const m = /^(-?)(\d+)(?:\.(\d{1,2}))?$/.exec(v); if (!m)
    throw new TravelError('E_TRAVEL_CSV_INVALID', `bad amount ${raw}`); return (m[1] === '-' ? -1 : 1) * (Number(m[2]) * 100 + Number((m[3] ?? '').padEnd(2, '0'))); }
function rows(t) { const l = t.trim().split(/\r?\n/).filter(Boolean); if (l.length < 2)
    throw new TravelError('E_TRAVEL_CSV_INVALID', 'CSV needs header+rows'); return l.map(x => x.split(',').map(y => y.trim())); }
function headerIndex(h, n) { const i = h.indexOf(n); if (i < 0)
    throw new TravelError('E_TRAVEL_CSV_INVALID', `missing ${n}`); return i; }
export function parseTrips(t) {
    const r = rows(t);
    const h = r[0].map(x => x.toLowerCase());
    const ti = headerIndex(h, 'trip_id'), ei = headerIndex(h, 'employee'), oi = headerIndex(h, 'origin'), di = headerIndex(h, 'destination'), dti = headerIndex(h, 'date'), ai = headerIndex(h, 'amount');
    return r.slice(1).map(c => { const trip = { trip_id: c[ti] ?? '', employee: c[ei] ?? '', origin: c[oi] ?? '', destination: c[di] ?? '', date: c[dti] ?? '', amount_cents: cents(c[ai] ?? '') }; if (!trip.trip_id)
        throw new TravelError('E_TRAVEL_CSV_INVALID', 'empty trip_id'); return trip; });
}
export function parseInvoices(t) {
    const r = rows(t);
    const h = r[0].map(x => x.toLowerCase());
    const ii = headerIndex(h, 'invoice_id'), ti = headerIndex(h, 'trip_id'), ai = headerIndex(h, 'amount');
    return r.slice(1).map(c => { const invoice = { invoice_id: c[ii] ?? '', trip_id: c[ti] ?? '', amount_cents: cents(c[ai] ?? '') }; if (!invoice.invoice_id)
        throw new TravelError('E_TRAVEL_CSV_INVALID', 'empty invoice_id'); return invoice; });
}
export function parseCards(t) {
    const r = rows(t);
    const h = r[0].map(x => x.toLowerCase());
    const ti = headerIndex(h, 'txn_id'), tri = headerIndex(h, 'trip_id'), ai = headerIndex(h, 'amount');
    return r.slice(1).map(c => { const card = { txn_id: c[ti] ?? '', trip_id: c[tri] ?? '', amount_cents: cents(c[ai] ?? '') }; if (!card.txn_id)
        throw new TravelError('E_TRAVEL_CSV_INVALID', 'empty txn_id'); return card; });
}
/** Duplicate trip ids in the raw CSV rows; the first occurrence is kept, the rest are reported. */
export function duplicateTrips(trips) {
    const counts = new Map();
    for (const trip of trips)
        counts.set(trip.trip_id, (counts.get(trip.trip_id) ?? 0) + 1);
    return [...counts.entries()].filter(([, occurrences]) => occurrences > 1).map(([trip_id, occurrences]) => ({ trip_id, occurrences }));
}
